package cpamp

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

// Derive uses half-open provider intervals [start, reset). The event timestamp
// is CPA's request start. A straddling request is counted once at start and is
// explicitly uncertain: aggregate token totals cannot reveal a token-time split.
// Multiple kinds/scopes are independent denominators and must never be added.
func Derive(a Account, observations []Observation, events []Event, now int64) []Window {
	groups := map[string][]Observation{}
	ordered := append([]Observation(nil), observations...)
	sort.SliceStable(ordered, func(i, j int) bool {
		if ordered[i].Observed == ordered[j].Observed {
			return ordered[i].ID < ordered[j].ID
		}
		return ordered[i].Observed < ordered[j].Observed
	})
	boundaryIndex := map[string][]string{}
	latest := map[string]int64{}
	for _, o := range ordered {
		if o.Reset > 0 && o.Start > 0 && o.Reset > o.Start {

			id := o.WindowID
			key := o.Kind + "|" + o.Scope
			bucket := o.Reset / 2001
			found := false
			for b := bucket - 1; b <= bucket+1 && !found; b++ {
				for _, candidate := range boundaryIndex[fmt.Sprintf("%s|%d", key, b)] {
					first := groups[candidate][0]
					if abs64(first.Reset-o.Reset) <= 2000 && abs64(first.Start-o.Start) <= 2000 {
						id = candidate
						found = true
						break
					}
				}
			}
			if !found {
				boundaryIndex[fmt.Sprintf("%s|%d", key, bucket)] = append(boundaryIndex[fmt.Sprintf("%s|%d", key, bucket)], id)
			}
			groups[id] = append(groups[id], o)
			if o.Observed > latest[key] {
				latest[key] = o.Observed
			}
		}
	}
	out := make([]Window, 0, len(groups)+1)
	for id, obs := range groups {
		sort.Slice(obs, func(i, j int) bool {
			if obs[i].Observed == obs[j].Observed {
				return obs[i].ID < obs[j].ID
			}
			return obs[i].Observed < obs[j].Observed
		})
		first, last := obs[0], obs[len(obs)-1]
		allZero := true
		for _, o := range obs {
			if o.Used == nil || *o.Used != 0 {
				allZero = false
			}
		}
		idle := allZero && abs64(first.Start-first.Observed) <= 10000

		if idle && last.Observed < latest[first.Kind+"|"+first.Scope] {
			continue
		}
		w := Window{ID: id, Account: a.ID, Provider: a.Provider, Label: a.Label, Kind: first.Kind, Scope: first.Scope, Models: first.Models, Start: first.Start, Reset: first.Reset, Duration: first.Duration, Status: "closed", Coverage: "observed interval", Notes: []string{}, FirstObserved: first.Observed, LastObserved: last.Observed, Observations: int64(len(obs)), Final: last.Used}
		w.ResetEarliest = first.Reset
		w.ResetLatest = first.Reset
		startEarliest, startLatest := first.Start, first.Start
		for _, o := range obs {
			w.ObservationIDs = append(w.ObservationIDs, o.ID)
			w.ResetEarliest = min(w.ResetEarliest, o.Reset)
			w.ResetLatest = max(w.ResetLatest, o.Reset)
			startEarliest = min(startEarliest, o.Start)
			startLatest = max(startLatest, o.Start)
		}
		if now < w.Reset {
			w.Status = "current"
		}
		if now < w.Start {
			w.Status = "not_started"
		}
		w.AttributionEnd = w.Reset

		for otherID, other := range groups {
			if otherID == id {
				continue
			}
			next := other[0]
			if next.Kind != w.Kind || next.Scope != w.Scope || next.Start >= w.Reset || next.Reset <= w.Start {
				continue
			}
			if next.Used != nil && *next.Used == 0 && abs64(next.Start-next.Observed) <= 10000 {
				continue
			}
			w.BoundaryRevision = true
			if next.Observed > last.Observed && next.Observed < w.AttributionEnd {
				w.AttributionEnd = next.Observed
				copy := next
				w.RevisionEvidence = &copy
				w.Status = "superseded"
			}
		}
		if w.BoundaryRevision {
			w.Notes = append(w.Notes, "Provider reported materially overlapping reset boundaries for the same scope. Superseded attribution stops at the first later observation; overlap is uncertain and projections are withheld.")
		}
		for _, o := range obs {
			if o.Used != nil && (w.Peak == nil || *o.Used > *w.Peak) {
				p := *o.Used
				w.Peak = &p
			}
		}
		if w.Final != nil {
			r := math.Max(0, 100-*w.Final)
			w.Remaining = &r
		}
		for _, e := range events {
			if matches(e, w.Scope, w.Models) && ((e.Started >= w.ResetEarliest && e.Started < w.ResetLatest) || (e.Started >= startEarliest && e.Started < startLatest)) {
				w.BoundaryUncertain++
			}
			if e.Started < w.Start || e.Started >= w.AttributionEnd || !matches(e, w.Scope, w.Models) {
				continue
			}
			w.Requests++
			addTokens(&w.Tokens, e.Tokens)
			if e.Failed {
				w.Failed++
			}
			if e.CostNano == nil {
				w.Unpriced++
			} else {
				w.CostNano += *e.CostNano
			}
			if e.Completed >= w.Reset {
				w.Straddling++
			}
			if e.HeaderTime > 0 && (e.HeaderTime < e.Started-5000 || e.HeaderTime > e.Completed+5000) {
				w.ClockSkew++
			}
		}
		if len(events) == 0 || events[0].Started > w.Start {
			w.Coverage = "partial history"
			w.Notes = append(w.Notes, "Gateway history begins after this window started.")
		}
		if idle {
			w.Coverage = "idle quota; reset is provider forecast"
			w.Notes = append(w.Notes, "Unused quota reports now + duration until a cycle activates; older idle forecasts remain in the token ledger evidence.")
		}
		if strings.HasPrefix(w.Scope, "unknown") {
			w.Coverage = "model scope unknown; token assignment unavailable"
		}
		if w.ResetEarliest != w.ResetLatest {
			w.Notes = append(w.Notes, "Provider boundaries differ by up to two seconds; first-observed boundary is canonical and exact raw boundaries remain in evidence.")
		}
		if w.BoundaryUncertain > 0 {
			w.Notes = append(w.Notes, "Requests fall inside the provider boundary precision band; exact provider assignment cannot be proven.")
		}
		if w.Straddling > 0 {
			w.Notes = append(w.Notes, "Requests cross reset: counted at request start; provider token-time allocation is unavailable.")
		}
		if w.ClockSkew > 0 {
			w.Notes = append(w.Notes, "Provider Date differs from request interval; clock uncertainty is retained.")
		}
		if w.Unpriced > 0 {
			w.Notes = append(w.Notes, "Cost is partial: some requests have no captured list price.")
		}
		w.Notes = append(w.Notes, "Last observed % is not a measurement at reset. Quota can include usage outside this gateway.")
		if now-last.Observed > 600000 && w.Status == "current" {
			w.Notes = append(w.Notes, "Quota observation is older than 10 minutes.")
		}

		if first.Used != nil && last.Used != nil && last.Observed > first.Observed {
			delta := *last.Used - *first.Used
			monotonic := true
			for i := 1; i < len(obs); i++ {
				if obs[i].Used != nil && obs[i-1].Used != nil && *obs[i].Used < *obs[i-1].Used {
					monotonic = false
				}
			}
			w.CalibrationStart = first.Observed
			w.CalibrationEnd = last.Observed
			w.CalibrationDelta = &delta
			for _, e := range events {
				if e.Started >= first.Observed && e.Completed <= last.Observed && e.Started >= w.Start && e.Completed < w.Reset && matches(e, w.Scope, w.Models) {
					w.CalibrationTokens += e.Tokens.Total
				}
			}
			if delta >= 1 && monotonic && w.CalibrationTokens > 0 && w.ClockSkew == 0 && w.Straddling == 0 && w.BoundaryUncertain == 0 && !w.BoundaryRevision {
				per := float64(w.CalibrationTokens) / delta
				limit := per * 100
				remaining := per * math.Max(0, 100-*last.Used)
				w.TokensPerPercent = &per
				w.EstimatedLimit = &limit
				w.EstimatedRemaining = &remaining
				if w.Status == "current" && now-last.Observed <= 600000 {
					exhaust := last.Observed + int64(float64(last.Observed-first.Observed)*math.Max(0, 100-*last.Used)/delta)
					w.Exhaustion = &exhaust
				}
				w.Notes = append(w.Notes, "Projection is an observed token/% ratio, assumes the same model/cache mix and no external usage; rounded provider % limits precision.")
			}
		}
		out = append(out, w)
	}

	{
		start := int64(0)
		if len(events) > 0 {
			start = events[0].Started
		}
		w := Window{ID: "ledger:" + a.ID, Account: a.ID, Provider: a.Provider, Label: a.Label, Kind: "ledger", Scope: "all", Start: start, Status: "history", Coverage: "token history; no quota denominator", Notes: []string{"All recorded requests, including periods without quota evidence. Do not add this ledger to quota windows."}}
		for _, e := range events {
			w.Requests++
			addTokens(&w.Tokens, e.Tokens)
			if e.CostNano == nil {
				w.Unpriced++
			} else {
				w.CostNano += *e.CostNano
			}
			if e.Failed {
				w.Failed++
			}
		}
		out = append(out, w)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Reset > out[j].Reset })
	return out
}

func abs64(n int64) int64 {
	if n < 0 {
		return -n
	}
	return n
}
